using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class TransformationResourceOperations : RefCounted
{
    private static string NewId()=>ActorData.new_id();
    private static Resource New(string name)=>name switch { "transformation_state"=>new KiwiTransformationState(), "transformation_key"=>new KiwiTransformationKey(), "transformation_component"=>new KiwiTransformationComponent(), "transformation_document"=>new KiwiTransformationImage2D(), _=>throw new ArgumentException("Unknown transformation resource: "+name) };
    private static void Copy(Resource first,Resource last,params string[] fields){foreach(string field in fields)last.Set(field,first.Get(field));}
    public Resource? lookup(Resource owner,string field,string id){foreach(var raw in owner.Get(field).AsGodotArray()){var item=raw.As<Resource>();if(item.Get("id").AsString()==id)return item;}return null;}
    public GArray sorted_keys(Resource owner){var source=owner.Get("keys").AsGodotArray();var result=source.Duplicate();var sorted=new List<Variant>(source);sorted.Sort((a,b)=>a.AsGodotObject().Get("time").AsDouble().CompareTo(b.AsGodotObject().Get("time").AsDouble()));result.Clear();foreach(var value in sorted)result.Add(value);return result;}
    public Resource copy_component(Resource owner,bool newIdentity)
    {
        var result=New("transformation_component");Copy(owner,result,"title","visible","locked","base_size");result.Set("id",newIdentity?Variant.From(NewId()):owner.Get("id"));var mapping=new Dictionary<string,string>();foreach(var raw in owner.Get("states").AsGodotArray()){var state=raw.As<Resource>();var copy=copy_state(state,newIdentity);copy.Get("artwork").AsGodotObject().Set("id",result.Get("id"));mapping[state.Get("id").AsString()]=copy.Get("id").AsString();result.Get("states").AsGodotArray().Add(copy);}string fallback=owner.Get("default_state_id").AsString();result.Set("default_state_id",mapping.TryGetValue(fallback,out var id)?id:fallback);foreach(var raw in owner.Get("keys").AsGodotArray()){var copy=copy_key(raw.As<Resource>(),newIdentity);string stateId=raw.AsGodotObject().Get("state_id").AsString();copy.Set("state_id",mapping.TryGetValue(stateId,out var mapped)?mapped:stateId);result.Get("keys").AsGodotArray().Add(copy);}return result;
    }
    public Resource copy_state(Resource owner,bool newIdentity){var result=New("transformation_state");Copy(owner,result,"title","pivot","revision");result.Set("id",newIdentity?Variant.From(NewId()):owner.Get("id"));var artwork=owner.Get("artwork").AsGodotObject();result.Set("artwork",artwork!=null?artwork.Call("copy_layer"):default);return result;}
    public Vector2 anchor(Resource owner){var artwork=owner.Get("artwork").AsGodotObject();return artwork.Call("local_transform").AsTransform2D()*(artwork.Get("dimensions").AsVector2()*owner.Get("pivot").AsVector2());}
    public Settings settings(Resource owner){string mode=owner.Get("mode").AsString();return new Settings {["alignment"]=owner.Get("alignment"),["preservation"]=owner.Get("preservation"),["quality"]=owner.Get("quality"),["strategy"]=mode is "Shape Morph" or "Guided Morph"?mode:"Auto Morph"};}
    public Resource copy_key(Resource owner,bool newIdentity){var result=New("transformation_key");Copy(owner,result,"id","time","state_id","mode","turns","reveal_width","alignment","preservation","appearance","quality","reveal_mode","origin_enabled","morph_origin","direction","topology_bias");foreach(string field in new[]{"points_a","points_b","reveal_path"})result.Set(field,owner.Get(field).AsVector2Array());if(newIdentity)result.Set("id",NewId());var curve=owner.Get("curve").As<Curve>();result.Set("curve",curve!=null?Variant.From(curve.Duplicate()):default);return result;}
    public double progress(Resource owner,double value){var curve=owner.Get("curve").As<Curve>();if(curve!=null)return Math.Clamp(curve.Sample((float)value),0,1);return owner.Get("mode").AsString() is "Smooth morph" or "Auto Morph" or "Shape Morph" or "Guided Morph"?Mathf.SmoothStep(0,1,value):value;}
    public Resource snapshot(Resource owner){var result=New("transformation_document");Copy(owner,result,"version","canvas_size","duration","preview_png");result.Set("workspace_state",owner.Get("workspace_state").AsGodotDictionary().Duplicate(true));result.Set("metadata",owner.Get("metadata").AsGodotDictionary().Duplicate(true));foreach(var raw in owner.Get("components").AsGodotArray())result.Get("components").AsGodotArray().Add(copy_component(raw.As<Resource>(),false));var events=result.Get("component_events").AsGodotArray();foreach(var raw in owner.Get("component_events").AsGodotArray().Duplicate(true))events.Add(raw);return result;}
    public Resource make_component(Vector2I size,string title){var item=New("transformation_component");item.Set("id",NewId());item.Set("title",title);item.Set("base_size",(Vector2)size);var state=New("transformation_state");state.Set("id",NewId());state.Set("title","Default");var artwork=KiwiImageLayer.create("basic",size);artwork.Set("id",item.Get("id"));artwork.Set("label",title);state.Set("artwork",artwork);item.Get("states").AsGodotArray().Add(state);item.Set("default_state_id",state.Get("id"));return item;}
    public Resource blank(Vector2I size){var result=New("transformation_document");result.Set("canvas_size",size);result.Get("components").AsGodotArray().Add(make_component(size,"Drawing"));return result;}
    public Texture2D? thumbnail(Resource owner){var bytes=owner.Get("preview_png").AsByteArray();if(bytes.Length==0)return null;using var image=new Image();return image.LoadPngFromBuffer(bytes)==Error.Ok?ImageTexture.CreateFromImage(image):null;}
}
